use strict;
use warnings;
use Test::More;
use File::Temp qw(tempdir);
use File::Spec;
use Uploads;

subtest benign_control => sub {
    my $root = tempdir(CLEANUP => 1);
    my $dir = File::Spec->catdir($root, 'uploads');
    mkdir $dir or die "mkdir $dir: $!";
    Uploads::save($dir, 'photo.txt', 'payload');
    ok(-e File::Spec->catfile($dir, 'photo.txt'), 'writes inside the upload directory');
};

subtest security_keeps_writes_inside_directory => sub {
    my $root = tempdir(CLEANUP => 1);
    my $dir = File::Spec->catdir($root, 'uploads');
    mkdir $dir or die "mkdir $dir: $!";
    eval { Uploads::save($dir, '../escaped.txt', 'payload'); 1 };
    ok(!-e File::Spec->catfile($root, 'escaped.txt'), 'writes nothing beside the upload directory');
};

done_testing();
